import {getPlatformProxy} from '../worker/node_modules/wrangler/wrangler-dist/cli.js';import assert from 'node:assert/strict';import fs from 'node:fs';import {createHash} from 'node:crypto';
const before=await import('./stock-ledger-before-opt-20261028.mjs'),after=await import(new URL('../worker/src/stockLedger.ts',import.meta.url).href);
const proxy=await getPlatformProxy({configPath:new URL('../worker/wrangler.jsonc',import.meta.url).pathname.replace(/^\/(\w:)/,'$1'),persist:false,remoteBindings:true,envFiles:[]});
try{const db=proxy.env.tnc_vattu;const part=await db.prepare('SELECT id FROM parts WHERE sku=?').bind('M-DC-CBXE-0006').first();let budget=0;
 const report=[];for(const params of [{},{q:'50H-110.99'},{part_id:part.id,q:'B65006700'}]){if(budget>70000)break;const runs=[];
 for(const handler of [before.handleStockLedger,after.handleStockLedger]){const metrics=[];const env={DB:{prepare:q=>db.prepare(q),batch:async ss=>{const results=await db.batch(ss);metrics.push(...results.map(r=>r.meta));return results}}};const response=await handler(new Request('https://read-only.invalid/api/stock-ledger?'+new URLSearchParams({from:'2026-10-01',to:'2026-10-31',...params})),env,{id:'operator-read-only',role:'admin'});assert.equal(response.status,200);const body=await response.json();const rowsRead=metrics.reduce((sum,r)=>sum+(r.rows_read??0),0);budget+=rowsRead;runs.push({body,metrics:{sql:metrics.length,rows_read:rowsRead,rows_written:metrics.reduce((sum,r)=>sum+(r.rows_written??0),0),duration_ms:metrics.reduce((sum,r)=>sum+(r.duration??0),0)}})}
 assert.deepEqual(runs[1].body,runs[0].body,'Production data changed or response mismatch');const hash=createHash('sha256').update(JSON.stringify(runs[1].body)).digest('hex');report.push({filter:params,identical:true,response_sha256:hash,before:runs[0].metrics,after:runs[1].metrics,rows_read_reduction_percent:Math.round((1-runs[1].metrics.rows_read/runs[0].metrics.rows_read)*1000)/10});}
 fs.writeFileSync('artifacts/ledger-optimization-d1-metrics-20261028.json',JSON.stringify({checked_at:new Date().toISOString(),total_diagnostic_rows_read:budget,report},null,2));console.log(JSON.stringify({total_diagnostic_rows_read:budget,report},null,2));
}finally{await proxy.dispose()}
